QGraphicsItem *noteItem(DrawingSheetEditor &e,QUuid id,const char *kind="annotation"){
 for(auto *i:e.canvas()->scene()->items())if(i->data(0).toString()==kind&&(id.isNull()||i->data(3).toUuid()==id))return i;
 return nullptr;
}
